### Change 1: lcd_put_rgb565 chunking

```c
int lcd_put_rgb565(const uint8_t *fb, int sw, int sh,
                   int dx, int dy, int dw, int dh)
{
  int fd = open("/dev/lcd0", O_WRONLY);
  uint8_t rowbuf[640];      /* 一块最大 320 像素 ×2B —— 不超驱动 rowbuff_be(640B) */
  struct lcddev_area_s area;
  int y;

  if (fd < 0)
    {
      printf("[LCD] open /dev/lcd0 failed: %d\n", fd);
      return -1;
    }

  if (dw > 480)
    {
      dw = 480;
    }

  memset(&area, 0, sizeof(area));
  area.stride = 0;

  for (y = 0; y < dh; y++)
    {
      int sy = (y * sh) / dh;    /* 最近邻：目标行 → 源行 */
      int x0;

      if (sy >= sh)
        {
          sy = sh - 1;
        }

      /* 分块写：每块 ≤320 像素（640B）。st7789 非 3WIRE 的字节交换缓冲
       * rowbuff_be 只有 ST7789_XRES×2=640B，块宽若超过 320 像素，wrram
       * 的整块交换会越界横扫 .bss（实测改写 g_cam_byte_swap/g_cam_quiet/
       * shutdown_handlers/g_cam_rxbuf —— swap 随机翻转、rxbuf 帧头被毁）。 */

      for (x0 = 0; x0 < dw; x0 += 320)
        {
          int chunk = dw - x0;
          int x;

          if (chunk > 320)
            {
              chunk = 320;
            }

          for (x = 0; x < chunk; x++)
            {
              int sx = ((x0 + x) * sw) / dw;

              if (sx >= sw)
                {
                  sx = sw - 1;
                }

              rowbuf[x * 2]     = fb[sy * sw * 2 + sx * 2];
              rowbuf[x * 2 + 1] = fb[sy * sw * 2 + sx * 2 + 1];
            }

          area.col_start = dx + x0;
          area.col_end = dx + x0 + chunk - 1;
          area.row_start = dy + y;
          area.row_end = dy + y;
          area.data = rowbuf;
          ioctl(fd, LCDDEVIO_PUTAREA, (unsigned long)&area);
        }
    }

  close(fd);
  return 0;
}
```

