}", "new_string": "int lcd_put_rgb565(const uint8_t *fb, int sw, int sh,
                   int dx, int dy, int dw, int dh)
{
  int fd = open("/dev/lcd0", O_WRONLY);
  uint8_t rowbuf[640];      /* 一块最大 320 像素 × 2B（见下方越界说明） */
  struct lcddev_area_s area;
  int y;

  if (fd < 0)
    {
      printf("[LCD] open /dev/lcd0 failed: %d\n", fd);
      return -1;
    }

  if (dw > 480)
    {
      dw = 480;
    }

  memset(&area, 0, sizeof(area));
  area.stride = 0;

  for (y = 0; y < dh; y++)
    {
      int sy = (y * sh) / dh;    /* 最近邻：目标行 → 源行 */
      int x0;

      if (sy >= sh)
        {
          sy = sh - 1;
        }

      /* 每行分块写（每块 ≤320 像素 = 640B）。
       *
       * 越界背景（CAMERA_DEBUG_LOG 2.46/2.47）：st7789 非 3WIRE 路径的
       * 字节交换缓冲 rowbuff_be 只有 ST7789_XRES×2 = 640B（map 实测
       * 0x3fcb96a0, 0x280）。而横屏 480 宽的一行是 960B —— 整行一次
       * PUTAREA 时 wrram 的交换循环把整行数据写进 640B 缓冲，越界
       * 320B/行 横扫 .bss（紧邻的 shutdown_handlers / g_cam_quiet /
       * g_cam_byte_swap / g_cam_rxbuf 0x3fcb9920 起全部被覆写）→
       * swap 标志随机翻转、rxbuf 帧头被毁、quiet 失效。
       * 面板数据恰好自洽（交换循环先写越界区再 SPI_SNDBLOCK 读回），
       * 所以画面"看起来正常"，内存却在被悄悄破坏 —— 之前 swap 矛盾
       * （set_swap(false) 后 capture 打印 swap=on）就是它干的。
       * 约束：st7789.c / defconfig XRES/YRES 不动 → 只能调用方规避：
       * 每块 ≤ 320 像素，保证 wrram 交换不超 640B。 */

      for (x0 = 0; x0 < dw; x0 += 320)
        {
          int chunk = dw - x0;
          int x;

          if (chunk > 320)
            {
              chunk = 320;
            }

          for (x = 0; x < chunk; x++)
            {
              int sx = ((x0 + x) * sw) / dw;

              if (sx >= sw)
                {
                  sx = sw - 1;
                }

              rowbuf[x * 2]     = fb[sy * sw * 2 + sx * 2];
              rowbuf[x * 2 + 1] = fb[sy * sw * 2 + sx * 2 + 1];
            }

          area.col_start = dx + x0;
          area.col_end = dx + x0 + chunk - 1;
          area.row_start = dy + y;
          area.row_end = dy + y;
          area.data = rowbuf;
          ioctl(fd, LCDDEVIO_PUTAREA, (unsigned long)&area);
        }
    }

  close(fd);
  return 0;
}"}

