{"file_path": "/home/vboxuser/openvela/apps/graphics/lvgl/lvgl/src/drivers/nuttx/lv_nuttx_lcd.c", "new_string": "static void flush_cb(lv_display_t * disp, const lv_area_t * area_p,
                     uint8_t * color_p)
{
    lv_nuttx_lcd_t * lcd = disp->driver_data;
    int32_t area_w = area_p->x2 - area_p->x1 + 1;
    uint8_t px_size = lv_color_format_get_size(lv_display_get_color_format(disp));
    int32_t x0;

    /* st7789 非 3WIRE 的字节交换缓冲 rowbuff_be = ST7789_XRES*2 = 640B：
     * 一次 PUTAREA 的列宽若 >320 像素（横屏 480 宽 = 960B/行），驱动
     * wrram 的整块交换会越界横扫 .bss —— 紧邻的 g_cam_byte_swap /
     * g_cam_quiet / g_cam_rxbuf / shutdown_handlers 全被覆写，swap 标志
     * 随机翻转 → 摄像头帧颜色错乱（"彩色丝往下刷"的根源）。
     * 按列分块 ≤320px 并带整区 stride：驱动走行-by-行分支，每行交换
     * ≤640B，不再越界。 */
    for(x0 = area_p->x1; x0 <= area_p->x2; x0 += 320) {
        int32_t x1 = x0 + 319;

        if(x1 > area_p->x2) {
            x1 = area_p->x2;
        }

        lcd->area.row_start = area_p->y1;
        lcd->area.row_end   = area_p->y2;
        lcd->area.col_start = x0;
        lcd->area.col_end   = x1;
        lcd->area.stride    = area_w * px_size;
        lcd->area.data      = color_p + (x0 - area_p->x1) * px_size;
        ioctl(lcd->fd, LCDDEVIO_PUTAREA, (unsigned long) & (lcd->area));
    }

    lv_display_flush_ready(disp);
