static pthread_t s_preview_tid;
static volatile bool s_preview_run;
static volatile bool s_preview_freeze;

/* 预览零拷贝：capture 完成后 rxbuf 即最新帧（稳定到下一次 capture），
 * s_preview_seq 递增通知 LVGL；LVGL 渲染 rxbuf（esp32s3_cam_dvp_get_frame）。
 * 不额外占内存（rxbuf 驱动已有）；预览线程 capture 后节流 30ms，
 * 给 LVGL 渲染留时间，避免下一次 capture 覆盖正在渲染的帧。 */

static volatile uint32_t s_preview_seq;   /* 帧序号：每次 capture 完成 +1 */

static void *camera_preview_loop(void *arg)
{
  volatile bool eoi = false;
  int ret;

  (void)arg;

  /* OV3660 RGB565 大端输出（2.49 彩条实锤）：强制字节交换（防任何残留/误设） */

  esp32s3_cam_dvp_set_swap(true);
  esp32s3_cam_dvp_set_quiet(true);
  esp32s3_cam_dvp_init();
  esp32s3_cam_dvp_start();

  while (s_preview_run)
    {
      if (s_preview_freeze)
        {
          usleep(20000);
          continue;
        }

      ret = esp32s3_cam_dvp_capture(NULL, NULL, &eoi);
      if (ret < 0)
        {
          break;
        }

      /* rxbuf 已更新为最新帧，通知 LVGL */

      s_preview_seq++;

      /* 节流：给 LVGL 渲染留时间（rxbuf 被下一次 capture 覆盖前） */

      usleep(30000);
    }

  esp32s3_cam_dvp_stop();
  esp32s3_cam_dvp_set_quiet(false);
  return NULL;
}

int camera_preview_start(int x, int y, int w, int h)
{
  (void)x;
  (void)y;
  (void)w;
  (void)h;

  if (s_preview_run)
    {
      return 0;
    }

  s_preview_seq = 0;
  s_preview_freeze = false;
  s_preview_run = true;

  if (pthread_create(&s_preview_tid, NULL, camera_preview_loop, NULL) != 0)
    {
      s_preview_run = false;
      return -1;
    }

  return 0;
}"}

{"file_path": "/home/vboxuser/openvela/apps/plant-companion/ui/screens/screen_camera.c", "content": "/****************************************************************************
 * apps/plant-companion/ui/screens/screen_camera.c
 *
 * ② AI拍照 — 植物识别（动态预览直写 LCD 版）
 *
 * 预览 = `plant cam preview` 的逻辑同步到 UI：
 *   - camera_preview_start(33,63,414,184) 启动后台线程：连续 capture
 *     （静默）→ lcd_put_rgb565 直接把每帧画到取景框内部（绕过 LVGL
 *     渲染器 —— 本 LVGL 版本 lv_image 渲染 RGB565 缩放有 bug，是
 *     彩屏/彩色丝往下刷的根因之一）。
 *   - 画面尺寸 = 绿框内部 (33,63,414,184)，与 3px 绿框严丝合缝。
 *   - 取景框内部不放任何 LVGL 对象（不失效该区）→ LVGL 不会重绘盖掉
 *     画面；lv_nuttx_lcd.c flush_cb 已按列分块 ≤320px，消除 rowbuff_be
 *     越界（swap 标志被覆写 → 颜色错乱"彩色丝"的另一个根源）。
 *
 * 拍照：camera_preview_take() 冻结预览线程，最后一帧定格在 LCD RAM。
 ****************************************************************************/

#include <lvgl/lvgl.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#include "screen_camera.h"
#include "screen_diagnose.h"
#include "../ui_app.h"
#include "../theme/theme_plant.h"

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
#  include "../../components/camera_capture/camera_capture.h"
#endif

#ifdef CONFIG_PLANT_AI_MODULE
#  include "../../services/ai_service.h"
#endif

/****************************************************************************
 * Private Data
 ****************************************************************************/

static lv_obj_t *s_status_label;   /* 「AI识别中…」状态文字 */

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
/* 取景框（绿框）内部：viewport(30,60,420,190) + 3px 边框 → 内部
 * x 33..446, y 63..246 = 414×184，与 plant cam preview 直写区域一致 */
#define CAM_VIEW_X     33
#define CAM_VIEW_Y     63
#define CAM_VIEW_W     414
#define CAM_VIEW_H     184

static lv_timer_t *s_frame_timer;   /* 帧计数显示定时器（ui_task 上下文） */
static lv_obj_t *s_frame_label;     /* 右上角帧计数（调试用，不挡画面） */
static bool s_cam_configured;       /* OV3660 RGB565 已配置（避免每次重配） */
#endif

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void cam_on_back(lv_event_t *e)
{
  (void)e;
  ui_app_pop_screen();
}

/* AI 完成回调（ai 工作线程触发）：把诊断数据带到 ui_task 上下文 */

static void cam_ai_done(void *user_data,
                        const struct ai_service_result_s *result)
{
  lv_obj_t *diag;
  const char *name;
  char tags[64];
  char issue_desc[128];
  char advice[256];
  bool has_issue;
  (void)user_data;

#ifdef CONFIG_PLANT_AI_MODULE
  if (result != NULL && result->success)
    {
      name = (result->engine.image.disease[0] != '\0') ?
             result->engine.image.disease : "识别成功";

      snprintf(tags, sizeof(tags), "#植物 #诊断 #养护");
      snprintf(issue_desc, sizeof(issue_desc), "%s",
               result->engine.image.advice[0] != '\0' ?
               result->engine.image.advice : "看起来状态不错");
      snprintf(advice, sizeof(advice), "%s",
               result->engine.summary[0] != '\0' ?
               result->engine.summary : "继续保持哦~");
      has_issue = true;
    }
  else
#endif
    {
      /* 失败/AI未启用：回退演示数据（离线可演示） */

      name = "绿萝";
      snprintf(issue_desc, sizeof(issue_desc), "叶片有少量黄斑，可能是浇水过多");
      snprintf(advice, sizeof(advice), "建议：减少浇水频率，移到通风处");
      snprintf(tags, sizeof(tags), "#好养 #净化空气 #喜阴");
      has_issue = true;
    }

  /* 在 ui_task 上下文创建诊断页（LVGL 对象只能在 ui_task 操作） */

  diag = screen_diagnose_create();
  screen_diagnose_set(diag, name, "", 96, tags,
                      has_issue, issue_desc, advice);
  ui_app_push_screen(diag);

  if (s_status_label != NULL)
    {
      lv_label_set_text(s_status_label, "识别完成 ✓");
    }
}

/* 拍照：预览线程已持续直写取景框；拍照 = 冻结当前帧（画面定格在 LCD） */

static void cam_on_shoot(lv_event_t *e)
{
  (void)e;

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
  if (s_status_label != NULL)
    {
      lv_label_set_text(s_status_label, "拍摄完成 ✓");
    }

  camera_preview_take();

#  ifdef CONFIG_PLANT_AI_MODULE
  cam_ai_done(NULL, NULL);   /* 演示诊断（AI 服务器接入后替换） */
#  endif
#else
  cam_ai_done(NULL, NULL);
#endif
}

/* 页面销毁（返回）：停止预览线程 + 删除帧计数定时器 */

static void cam_on_delete(lv_event_t *e)
{
  (void)e;

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
  camera_preview_stop();

  if (s_frame_timer != NULL)
    {
      lv_timer_delete(s_frame_timer);
      s_frame_timer = NULL;
    }
#endif
}

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
/* LVGL 定时器：ui_task 上下文刷新右上角帧计数（只失效标签自身小区域，
 * 不碰取景框内部；同时证明预览线程活着）。 */

static void frame_timer_cb(lv_timer_t *timer)
{
  (void)timer;

  if (s_frame_label != NULL)
    {
      lv_label_set_text_fmt(s_frame_label, "帧 %d",
                            camera_preview_get_frame_index());
    }
}
#endif

/****************************************************************************
 * Public Functions
 ****************************************************************************/

lv_obj_t *screen_camera_create(void)
{
  lv_obj_t *scr = lv_obj_create(lv_screen_active());
  lv_obj_t *back;
  lv_obj_t *title;
  lv_obj_t *viewport;
  lv_obj_t *shoot;

  lv_obj_remove_style_all(scr);
  lv_obj_set_size(scr, 480, 320);
  lv_obj_set_style_bg_color(scr, lv_color_hex(0x0f172a), 0);
  lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);

  /* 顶部：返回 + 拍一拍 */

  back = lv_button_create(scr);
  lv_obj_remove_style_all(back);
  lv_obj_set_size(back, 96, TP_TOP_BAR_H);
  lv_obj_set_pos(back, 0, 0);
  lv_obj_set_style_text_color(back, lv_color_hex(0xffffff), 0);
  lv_obj_set_style_text_font(back, TP_FONT_BODY, 0);
  theme_btn_set_text(back, LV_SYMBOL_LEFT " 返回");
  lv_obj_add_event_cb(back, cam_on_back, LV_EVENT_CLICKED, NULL);

  title = lv_label_create(scr);
  lv_label_set_text(title, "拍一拍");
  lv_obj_set_style_text_font(title, TP_FONT_TITLE, 0);
  lv_obj_set_style_text_color(title, lv_color_hex(0xffffff), 0);
  lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 8);

  lv_obj_t *ai_tag = lv_label_create(scr);
  lv_label_set_text(ai_tag, "AI识别中");
  lv_obj_set_style_text_font(ai_tag, TP_FONT_BODY, 0);
  lv_obj_set_style_text_color(ai_tag, lv_color_hex(TP_CLR_PRIMARY_GREEN_LIGHT), 0);
  lv_obj_align(ai_tag, LV_ALIGN_TOP_RIGHT, -12, 12);
  s_status_label = ai_tag;

  /* 取景框（绿框）：只画边框，内部不放任何 LVGL 对象 ——
   * 直写预览线程把摄像头画面画满内部 (33,63,414,184)，严丝合缝 */

  viewport = lv_obj_create(scr);
  lv_obj_remove_style_all(viewport);
  lv_obj_set_size(viewport, 420, 190);
  lv_obj_set_pos(viewport, 30, 60);
  lv_obj_set_style_border_width(viewport, 3, 0);
  lv_obj_set_style_border_color(viewport, lv_color_hex(TP_CLR_PRIMARY_GREEN_LIGHT), 0);
  lv_obj_set_style_border_side(viewport, LV_BORDER_SIDE_FULL, 0);
  lv_obj_set_style_radius(viewport, TP_RADIUS_SMALL, 0);
  lv_obj_set_style_bg_color(viewport, lv_color_hex(0x1e293b), 0);
  lv_obj_set_style_bg_opa(viewport, LV_OPA_COVER, 0);

  /* 底部拍照按钮 */

  shoot = lv_button_create(scr);
  lv_obj_remove_style_all(shoot);
  lv_obj_add_style(shoot, &theme_style_btn_primary, 0);
  lv_obj_set_size(shoot, 120, 48);
  lv_obj_align(shoot, LV_ALIGN_BOTTOM_MID, 0, -12);
  lv_obj_set_style_radius(shoot, LV_RADIUS_CIRCLE, 0);
  theme_btn_set_text(shoot, LV_SYMBOL_IMAGE " 拍照");
  lv_obj_add_event_cb(shoot, cam_on_shoot, LV_EVENT_CLICKED, NULL);

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
  /* 手机相机式预览（直写 LCD，= plant cam preview 的逻辑）：
   * 后台线程 capture → lcd_put_rgb565 直写取景框内部；无 LVGL 对象
   * 与之竞争，无 lv_image 渲染 bug。 */

  if (camera_init() == 0)
    {
      if (!s_cam_configured)
        {
          if (camera_config_rgb565_qvga() == 0)
            {
              /* 首次配置含 1s AEC/AWB 收敛等待 */
              s_cam_configured = true;
            }
        }

      camera_preview_start(CAM_VIEW_X, CAM_VIEW_Y,
